import java.util.*;
import java.io.*;

public class Main {
    static final int MAX = 1000007;
    static int n, T;
    static char[][] s1 = new char[15][15];
    static char[][] s2 = new char[15][15];
    static int[][] id = new int[15][15];
    static int cnt;
    static int s, t;
    static int xz, yz;
    static int[][] dir = { {0,1}, {0,-1}, {1,0}, {-1,0} };

    static boolean inside(int x, int y) {
        return x >= 0 && y >= 0 && x < n && y < n && s1[x][y] >= '0' && s1[x][y] <= '9';
    }

    static List<Integer> vv = new ArrayList<>(Collections.nCopies(MAX, 0));
    static List<Integer> cap = new ArrayList<>(Collections.nCopies(MAX, 0));
    static List<Integer> nxt = new ArrayList<>(Collections.nCopies(MAX, 0));
    static int[] h = new int[210];
    static int e = 0;
    static int[] pre = new int[210];
    static int[] vis = new int[210];

    static void add_edge(int u, int v, int c) {
        vv.set(e, v); cap.set(e, c); nxt.set(e, h[u]); h[u] = e++;
        vv.set(e, u); cap.set(e, 0); nxt.set(e, h[v]); h[v] = e++;
    }

    static int max_flow() {
        int flow = 0;
        while (true) {
            Arrays.fill(pre, -1);
            Arrays.fill(vis, 0);
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            vis[s] = 1;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int i = h[u]; i != -1; i = nxt.get(i)) {
                    int v = vv.get(i);
                    if (cap.get(i) > 0 && vis[v] == 0) {
                        vis[v] = 1;
                        pre[v] = i;
                        if (v == t) gotoAugment(flow);
                        q.offer(v);
                    }
                }
            }
            break;
            // label for goto
            // Java doesn't support goto, so we simulate with a boolean
            // but for simplicity, we can use a labeled block
            // or a boolean flag
            // Here, we will use a boolean flag
        }
        return flow;
    }

    static int max_flow_with_augment() {
        int flow = 0;
        while (true) {
            Arrays.fill(pre, -1);
            Arrays.fill(vis, 0);
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            vis[s] = 1;
            boolean augmented = false;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int i = h[u]; i != -1; i = nxt.get(i)) {
                    int v = vv.get(i);
                    if (cap.get(i) > 0 && vis[v] == 0) {
                        vis[v] = 1;
                        pre[v] = i;
                        if (v == t) {
                            // augment
                            int f = Integer.MAX_VALUE;
                            for (int v2 = t; v2 != s; v2 = vv.get(pre[v2] ^ 1)) {
                                f = Math.min(f, cap.get(pre[v2]));
                            }
                            for (int v2 = t; v2 != s; v2 = vv.get(pre[v2] ^ 1)) {
                                cap.set(pre[v2], cap.get(pre[v2]) - f);
                                cap.set(pre[v2] ^ 1, cap.get(pre[v2] ^ 1) + f);
                            }
                            flow += f;
                            augmented = true;
                            break;
                        }
                        q.offer(v);
                    }
                }
                if (augmented) break;
            }
            if (!augmented) break;
        }
        return flow;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        T = Integer.parseInt(st.nextToken());

        for (int i = 0; i < n; i++) {
            s1[i] = br.readLine().toCharArray();
        }
        for (int i = 0; i < n; i++) {
            s2[i] = br.readLine().toCharArray();
        }

        Arrays.fill(h, -1);
        e = 0;
        for (int i = 0; i < MAX; i++) {
            vv.set(i, 0);
            cap.set(i, 0);
            nxt.set(i, 0);
        }
        for (int i = 0; i < 15; i++) {
            Arrays.fill(id[i], -1);
        }
        cnt = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (s1[i][j] == 'Z') {
                    xz = i; yz = j;
                } else if (inside(i, j)) {
                    id[i][j] = ++cnt;
                }
            }
        }
        s = 0; t = 2 * cnt + 1;

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (inside(i, j)) {
                    for (int d = 0; d < 4; ++d) {
                        int x = i + dir[d][0], y = j + dir[d][1];
                        if (inside(x, y)) {
                            if (s2[x][y] != 0) {
                                add_edge(id[i][j] + cnt, t, s2[x][y] - '0');
                            }
                            if (s1[i][j] == '0') continue;
                            add_edge(s, id[i][j], s1[i][j] - '0');
                            if (s2[x][y] != 0) {
                                add_edge(id[i][j], id[x][y] + cnt, 10);
                            }
                        }
                    }
                }
            }
        }
        System.out.println(max_flow_with_augment());
    }
}

